public static partial class ItalianQuotes
{
    public static class PrimoLevi
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Al fascismo di oggi manca soltanto il potere per ridiventare quello che era, e cioè la consacrazione del privilegio e della disuguaglianza.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "C'è Auschwitz, quindi non può esserci Dio. Non trovo una soluzione al dilemma. La cerco, ma non la trovo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "L'esperienza è l'accumulo del da farsi davanti all'imprevisto.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Le leggi razziali erano il sintomo di una carnevalata: si era ormai dimenticato il volto criminale del fascismo (quello del delitto Matteotti, per intenderci): rimaneva da vederne quello sciocco.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "È avvenuto, quindi può accadere di nuovo: questo è il nocciolo di quanto abbiamo da dire.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Non esistono problemi che non possano essere risolti intorno a un tavolo, purché ci sia volontà buona e fiducia reciproca: o anche paura reciproca.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Era di fantasia pedestre e lenta: viveva di sogni come tutti noi, ma i suoi sogni erano saggi, erano ottusi, possibili, contigui alla realtà, non romantici, non cosmici.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Chi va in caccia non ha che da prendere il fucile, anzi meglio la zagaglia e l'arco, e mettersi per il bosco: il successo e l'insuccesso dipendono solo da lui.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Distillare è bello. Prima di tutto, perché è un mestiere lento, filosofico e silenzioso, che ti occupa ma ti lascia tempo di pensare ad altro, un po' come l'andare in bicicletta.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Le grane, tu lo saprai, non vengono al galoppo, come gli Unni, ma zitte, di soppiatto, come le epidemie.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Una vernice è una sostanza instabile per definizione: infatti, a un certo punto della sua carriera, da liquida deve diventare solida. È necessario che questo avvenga al momento e nel luogo giusto.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Ammettevo che non tutti nascono eroi, e che un mondo in cui ''tutti'' fossero come lui, cioè onesti ed inermi, sarebbe tollerabile, ma questo è un mondo irreale.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Auschwitz è fuori di noi, ma è intorno a noi, è nell'aria. La peste si è spenta, ma l'infezione serpeggia: sarebbe sciocco negarlo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "È dell'uomo operare in vista di un fine: la strage di Auschwitz, che ha distrutto una tradizione ed una civiltà, non ha giovato a nessuno.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Hanno dimostrato per tutti i secoli a venire quali insospettate riserve di ferocia e di pazzia giacciano latenti nell'uomo dopo millenni di vita civile, e questa è opera demoniaca.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "In realtà, e nonostante alcune contrarie apparenze, il disconoscimento, il vilipendio del valore morale del lavoro era ed è essenziale al mito fascista in tutte le sue forme.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Ogni tempo ha il suo fascismo: se ne notano i segni premonitori dovunque la concentrazione di potere nega al cittadino la possibilità e la capacità di esprimere ed attuare la sua volontà.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = " [...] perché il martello aggiusta tutto, tanto che alla Lancia lo chiamavano \"l'ingegnere\".", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Pena e dispetto come fanno i malati, che anche se uno non gli vuole bene finisce col dare una mano perché guariscano, così almeno non si lamentano più.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Non è mica un caso che quelli che hanno più fretta di fare il funerale sono proprio quelli che sentono più colpa.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Lei deve sapere che farmi avanti quando tutti si fanno indietro a me mi è sempre piaciuto, e mi piace ancora.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Perché certe imprese per capirle bisogna farle, o almeno vederle;", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Perché quando c'è la fame uno si fa furbo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Perché la brava gente si somiglia dappertutto.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Ma sa come succede quando uno incontra una difficoltà e allora gli pare come se avesse fatto una scommessa e gli spiace di perderla.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Io ho idea che se certi lavori li insegnassero a scuola, invece di Romolo e Remo, si guadagnerebbe.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Può essere che invece non mi segua il lettore, qui ed altrove, dove è questione di mandrini, di molecole, di cuscinetti a sfere e di capicorda; bene, non so che farci, mi scuso ma sinonimi non ce n'è.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Ma per me un uomo che non abbia mai avuto un collaudo negativo non è un uomo, è come se fosse rimasto alla prima comunione.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Meglio sbagliare per omissione che per commissione: meglio astenersi dal governare il destino degli altri, dal momento che è già così difficile ed incerto pilotare il proprio.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Non salutavano, non sorridevano; apparivano oppressi, oltre che da pietà, da un confuso ritegno, che sigillava le loro bocche, e avvinceva i loro occhi allo scenario funereo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "I codici morali, tutti, sono rigidi per definizione: non ammettono sfumature, né compromessi, né contaminazioni reciproche. Vanno accolti o rifiutati in blocco.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Guerra è sempre.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Non è infrequente che dall'urto fra due necessità scaturiscano decisioni insensate, là dove sarebbe più savio lasciare che il dilemma si sciolga per virtù propria.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Nei suoi discorsi, il vero, il possibile e il fantastico erano intrecciati in un groviglio vario e inestricabile.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Perché il delfino è simile ad un pesce, eppure partorisce ed allatta i suoi nati? Perché è figlio di un tonno e di una vacca.", Author = "Primo Levi" },
        };
    }
}